function removeItem(
    id: string,
    modifiers?: CartModifier[],
    instructions?: string,
  ) {
    setOrder((prev) =>
      prev
        .map((ci) =>
          ci.item.id === id &&
          (!modifiers ||
            modifierSignature(ci.modifiers) === modifierSignature(modifiers)) &&
          (instructions === undefined ||
            (ci.specialInstructions ?? "") === instructions)
            ? { ...ci, quantity: ci.quantity - 1 }
            : ci,
        )
        .filter((ci) => ci.quantity > 0),
    );
